import{at as e,it as t,n,vt as r}from"./chunks/framework.CVSQIll4.js";var i=JSON.parse(`{"title":"Migrating to\xA06.0.0","description":"","frontmatter":{},"headers":[],"relativePath":"migration-guide/to-6.0.0.md","filePath":"docs/migration-guide/to-6.0.0.md","lastUpdated":1792858263000}`),a={name:`migration-guide/to-6.0.0.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="migrating-to-6-0-0" tabindex="-1">Migrating to\xA06.0.0 <a class="header-anchor" href="#migrating-to-6-0-0" aria-label="Permalink to “Migrating to\xA06.0.0”">​</a></h1><p>This guide is intended to\xA0help you migrate to\xA0version\xA06.0.0 of\xA0<code>@styistic/stylelint-plugin</code>. It covers only the\xA0required steps and\xA0a\xA0few useful tips. It does not\xA0cover every change; see the\xA0<a href="/changelog">changelog</a> for\xA0the\xA0complete list.</p><h2 id="common-to-all-syntaxes" tabindex="-1">Common to\xA0all syntaxes <a class="header-anchor" href="#common-to-all-syntaxes" aria-label="Permalink to “Common to\xA0all syntaxes”">​</a></h2><p>First, upgrade both <code>@styistic/stylelint-plugin</code> to\xA0version\xA06 and\xA0<code>stylelint</code> itself to\xA0version\xA018.</p><p>After\xA0that, most configurations should continue to\xA0work as-is if\xA0you don&#39;t use custom syntaxes. However, some changes may also be necessary for\xA0configurations targeting plain CSS.</p><h3 id="rule-migration" tabindex="-1">Rule migration <a class="header-anchor" href="#rule-migration" aria-label="Permalink to “Rule migration”">​</a></h3><p>The\xA0<code>declaration-block-single-line-max-declarations</code> rule from\xA0<code>stylelint</code> <a href="/rules/declaration-block-single-line-max-declarations">has moved to\xA0the\xA0plugin</a>. If\xA0your configuration includes this rule, either add the\xA0<code>@stylistic/</code> namespace to\xA0its name or\xA0move it to\xA0the\xA0new <a href="/user-guide/typed-configuration"><code>defineStylistic</code> and\xA0<code>defineStylisticOverride</code></a> functions.</p><h3 id="conflicting-settings" tabindex="-1">Conflicting settings <a class="header-anchor" href="#conflicting-settings" aria-label="Permalink to “Conflicting settings”">​</a></h3><p>A\xA0pair of\xA0<a href="/user-guide/conflicting-settings">conflicting settings</a> now causes the\xA0run to\xA0fail with\xA0a\xA0configuration error that\xA0identifies both settings and\xA0provides suggestions for\xA0fixing the\xA0issue. If\xA0you encounter this warning, simply update your configuration according to\xA0one of\xA0the\xA0suggestions.</p><p>Using the\xA0new <a href="/user-guide/typed-configuration"><code>defineStylistic</code> and\xA0<code>defineStylisticOverride</code></a> functions helps prevent such conflicts not\xA0only when\xA0the\xA0configuration is loaded, but\xA0also at\xA0the\xA0type level in\xA0your editor.</p><h3 id="new-warnings-and-autofixes" tabindex="-1">New warnings and\xA0autofixes <a class="header-anchor" href="#new-warnings-and-autofixes" aria-label="Permalink to “New warnings and\xA0autofixes”">​</a></h3><p>The\xA0plugin includes many improvements, such as\xA0fixing numerous false-negative bugs, removing the\xA0dependency of\xA0autofix results on\xA0rule order in\xA0the\xA0configuration, expanding the\xA0scope of\xA0some rules, and\xA0more.</p><p>However, because\xA0every rule in\xA0the\xA0plugin now supports autofixing except <code>max-line-length</code> (which\xA0cannot be autofixed), you don&#39;t need to\xA0review all these improvements individually. Just run linting with\xA0<code>--fix</code> and\xA0review the\xA0resulting changes to\xA0your project&#39;s styles.</p><h2 id="namespaces-for-custom-syntaxes" tabindex="-1">Namespaces for\xA0custom syntaxes <a class="header-anchor" href="#namespaces-for-custom-syntaxes" aria-label="Permalink to “Namespaces for\xA0custom syntaxes”">​</a></h2><p>Rules under\xA0their base names now read stylesheets only as\xA0plain CSS. If\xA0your configuration processes a\xA0syntax other than\xA0CSS through\xA0an\xA0<code>overrides</code> block with\xA0<code>customSyntax</code>, rename the\xA0rules in\xA0that\xA0block to\xA0use the\xA0namespace for\xA0that\xA0syntax:</p><div class="language-diff"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">diff</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">export default {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    overrides: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            files: [&quot;**/*.scss&quot;],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            customSyntax: &quot;postcss-scss&quot;,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            rules: {</span></span>
<span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">-               &quot;@stylistic/indentation&quot;: &quot;tab&quot;,</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">+               &quot;@stylistic/scss/indentation&quot;: &quot;tab&quot;,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Use <code>less</code> or\xA0<code>styled</code> instead of\xA0<code>scss</code> for\xA0the\xA0other two\xA0syntaxes.</p><p>The\xA0new <a href="/user-guide/typed-configuration"><code>defineStylistic</code> and\xA0<code>defineStylisticOverride</code></a> functions let you avoid specifying a\xA0namespace for\xA0every rule. You specify the\xA0syntax once for\xA0the\xA0entire block, so\xA0rules keep their short names and\xA0can even omit the\xA0<code>@stylistic/</code> prefix. When\xA0using these functions with\xA0custom syntaxes, you&#39;ll also need to\xA0install the\xA0corresponding syntax package in\xA0your project (for\xA0example, <code>postcss-scss</code> for\xA0<code>scss</code>). These packages are not\xA0bundled with\xA0the\xA0plugin, to\xA0avoid adding unnecessary dependencies to\xA0your projects.</p><h2 id="new-features-optional" tabindex="-1">New features (optional) <a class="header-anchor" href="#new-features-optional" aria-label="Permalink to “New features (optional)”">​</a></h2><p>Check out the\xA0“<a href="/changelog#new-rules">New rules</a>” and\xA0“<a href="/changelog#new-options">New options</a>” sections of\xA0the\xA0changelog. Many of\xA0these additions are likely to\xA0be useful.</p><p>Alternatively, if\xA0you don&#39;t want to\xA0review them individually, use the\xA0new built-in\xA0<a href="/user-guide/configs"><code>@stylistic/stylelint-plugin/recommended</code></a> preset by\xA0adding it to\xA0your config&#39;s <code>extends</code> field. Although\xA0the\xA0preset is opinionated, its settings work well together and\xA0provide convenient style formatting. It also already includes most of\xA0the\xA0new rules and\xA0options, and\xA0will continue to\xA0gain new settings as\xA0features are added to\xA0the\xA0plugin. You can always override any settings in\xA0the\xA0preset that\xA0don&#39;t suit your needs.</p>`,21)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};